const data = $json;

const errors = [];

const applicationId = String(data["Application ID"] ?? "").trim();
const candidateName = String(data["Candidate Name"] ?? "").trim();
const email = String(data["Email"] ?? "").trim();
const consent = String(data["Consent Status"] ?? "").trim();

if (!applicationId) {
  errors.push("Missing Application ID.");
}

if (!candidateName) {
  errors.push("Missing Candidate Name.");
}

if (!email) {
  errors.push("Missing candidate email address.");
} else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
  errors.push("Invalid email address format.");
}

if (consent.toLowerCase() !== "yes") {
  errors.push("Candidate consent is missing or not confirmed.");
}

const notificationReady = errors.length === 0;

return {
  json: {
    ...data,
    applicationId,
    candidateName,
    candidateEmail: email,
    notificationReady,
    notificationValidationErrors: errors
  }
};

